# Safe loss function that returns large value on NaN/inf
def safe_minimize(func, x0, **kwargs):
    def wrapped(params):
        val = func(params)
        if np.isnan(val) or np.isinf(val):
            return 1e20
        return val
    return minimize(wrapped, x0, **kwargs)

# Form 1: L = A * N^(-alpha) + B * C^(-beta) + c * log(V) + E
def form1(params):
    A, alpha, B, beta, c, E = params
