    return np.mean((L - pred)**2)

# Form 2: L = A * N^(-alpha) + B * C^(-beta) + c/V^gamma + E
def form2(params):
    A, alpha, B, beta, c, gamma, E = params
    pred = A * N**(-alpha) + B * C**(-beta) + c * V**(-gamma) + E
    return np.mean((L - pred)**2)

# Form 3: L = A * (N + c*V)^(-alpha) + B * C^(-beta) + E
def form3(params):
    A, c, alpha, B, beta, E = params
    total = N + c * V
    if np.any(total <= 0):
        return 1e20
    pred = A * total**(-alpha) + B * C**(-beta) + E
    return np.mean((L - pred)**2)

# Form 4: L = A * N^(-alpha) + B * C^(-beta) + c * log(V)/N^delta + E
def form4(params):
    A, alpha, B, beta, c, delta, E = params
    pred = A * N**(-alpha) + B * C**(-beta) + c * np.log(V) * N**(-delta) + E
    return np.mean((L - pred)**2)

# Form 5: L = A * N^(-alpha) + B * C^(-beta) + c * V^(-gamma) * N^(-delta) + E
def form5(params):
    A, alpha, B, beta, c, gamma, delta, E = params
    pred = A * N**(-alpha) + B * C**(-beta) + c * V**(-gamma) * N**(-delta) + E
    return np.mean((L - pred)**2)

