    a,b,c,d = p
    pred = a*logN + b*logC + c*logV + d
    return safe_mse(pred)

# Form: L = A*N^(-a) + B*C^(-b) + c*log(V) + d  (with good init)
def f_chinchilla_logv(p):
    A,a,B,b,c,d = p
    pred = A*N**(-a) + B*C**(-b) + c*logV + d
    return safe_mse(pred)

# Form: L = A*N^(-a) + B*C^(-b) + c*V^(-g) + d
def f_chinchilla_vpow(p):
    A,a,B,b,c,g,d = p
    pred = A*N**(-a) + B*C**(-b) + c*V**(-g) + d
    return safe_mse(pred)

# Form with interaction: L = A*N^(-a) + B*C^(-b) + (c + d*log(N))*log(V) + E
def f_interact2(p):
    A,a,B,b,c,d,E = p
    pred = A*N**(-a) + B*C**(-b) + (c + d*logN)*logV + E
    return safe_mse(pred)

# Form: L = A*N^(-a) + B*C^(-b) + c*log(V)/C^d + E
def f_v_over_c(p):
    A,a,B,b,c,d,E = p
    pred = A*N**(-a) + B*C**(-b) + c*logV*C**(-d) + E
    return safe_mse(pred)

# Log-linear first
